begin;
create schema if not exists auth;
create table if not exists auth.users(id uuid primary key,email text,email_confirmed_at timestamptz,encrypted_password text,raw_app_meta_data jsonb);
create table if not exists auth.sessions(id uuid primary key,user_id uuid);
do $$<<audit>> declare root uuid:=gen_random_uuid();adm uuid:=gen_random_uuid();c uuid:=gen_random_uuid();p jsonb;n integer;version integer;before_brand text;path text:='products/'||gen_random_uuid()||'.webp';url text;product uuid;candidate jsonb;legacy_path text;legacy_url text;f regprocedure;
begin
 insert into public.profiles(id,full_name,email,username,role,staff_status,cashier_pin_enabled) values
 (root,'Root','hard-root@example.test','hard.root','superadmin','active',false),
 (adm,'Admin','hard-admin@example.test','hard.admin','admin','active',false),
 (c,'Cashier','hard-cashier@example.test','hard.cashier','cashier','active',true);
 select session_version into version from public.profiles where id=c;
 begin perform public.begin_staff_edit(adm,c,'Cashier','next@example.test','hard.next','admin');raise exception 'Privilege escalation accepted';exception when insufficient_privilege then null;end;
 begin perform public.archive_staff_account(root,root);raise exception 'Self archive accepted';exception when insufficient_privilege then null;end;
 insert into auth.sessions values(gen_random_uuid(),c);
 p:=public.begin_staff_edit(root,c,'New name','new-identity@example.test','hard.new','admin');
 if p->>'staff_status'<>'invited' or exists(select 1 from auth.sessions where user_id=c) then raise exception 'Edit did not suspend and revoke';end if;
 begin perform tkm.check_staff_session(c,version);raise exception 'Old session passed';exception when insufficient_privilege then null;end;
 begin perform public.finish_staff_edit(root,c,(p->>'session_version')::int,'password');raise exception 'Missing Auth provisioning accepted';exception when check_violation then null;end;
 insert into auth.users values(c,'new-identity@example.test',now(),'synthetic-only',jsonb_build_object('staff_session_version',p->'session_version','staff_access_method','password'));
 p:=public.finish_staff_edit(root,c,(p->>'session_version')::int,'password');
 if p->>'role'<>'admin' or p->>'staff_status'<>'active' then raise exception 'Role edit failed';end if;
 begin perform public.archive_staff_account(adm,c);raise exception 'Peer admin archive accepted';exception when insufficient_privilege then null;end;
 p:=public.archive_staff_account(root,c);
 begin perform public.begin_staff_password(root,c,true);raise exception 'Archived account activated';exception when check_violation then null;end;
 if not exists(select 1 from public.profiles where id=c and archived_at is not null and staff_status='disabled') then raise exception 'Archive deleted history identity';end if;
 p:=public.archive_staff_account(root,c,true);
 if p->>'staff_status'<>'disabled' or p->>'archived_at' is not null then raise exception 'Restore activated credentials';end if;
 p:=public.begin_staff_edit(root,c,'Cashier again','cashier-again@example.test','hard.again','cashier');
 update auth.users set email='cashier-again@example.test',raw_app_meta_data=jsonb_build_object('staff_session_version',p->'session_version','staff_access_method','pin') where id=c;
 p:=public.finish_staff_edit(root,c,(p->>'session_version')::int,'pin');
 if p->>'staff_status'<>'disabled' then raise exception 'Edit enabled disabled account';end if;
 p:=public.begin_staff_password(root,c,true);
 update auth.users set raw_app_meta_data=jsonb_build_object('staff_session_version',p->'session_version','staff_access_method','pin') where id=c;
 p:=public.finish_staff_credential(root,c,(p->>'session_version')::int,'pin');version:=(p->>'session_version')::int;
 for n in 1..5 loop perform public.claim_cashier_pin_attempt(c);end loop;
 begin perform public.claim_cashier_pin_attempt(c);raise exception 'Untrusted budget bypass';exception when sqlstate 'P0001' then if sqlerrm<>'PIN_ATTEMPTS_EXCEEDED' then raise;end if;end;
 p:=public.claim_trusted_cashier_attempt(c,repeat('a',64),version);
 if p is null then raise exception 'Foreign guesses locked trusted browser';end if;
 begin perform public.claim_trusted_cashier_attempt(c,repeat('b',64),version-1);raise exception 'Old trusted token accepted';exception when sqlstate 'P0001' then if sqlerrm<>'PIN_ATTEMPTS_EXCEEDED' then raise;end if;end;
 perform public.finish_trusted_cashier_login(c,version,repeat('a',64));
 if exists(select 1 from tkm.cashier_device_attempts where cashier_id=c) then raise exception 'Successful login kept attempts';end if;
 perform public.manage_staff_account(root,c,'disable');
 p:=public.begin_staff_edit(root,c,'Cashier again','cashier-again@example.test','hard.again','cashier');
 if not exists(select 1 from tkm.staff_edits where profile_id=c and keep_disabled) then raise exception 'Disabled edit not remembered';end if;
 p:=public.begin_staff_password(root,c,true);
 if exists(select 1 from tkm.staff_edits where profile_id=c) then raise exception 'Reset retained abandoned edit';end if;
 update auth.users set raw_app_meta_data=jsonb_build_object('staff_session_version',p->'session_version','staff_access_method','pin') where id=c;
 perform public.finish_staff_credential(root,c,(p->>'session_version')::int,'pin');
 select brand_name into before_brand from public.settings where id=1;
 begin perform public.save_restaurant_settings(root,'Partial should rollback','',101,0,false,false);raise exception 'Invalid pricing saved';exception when check_violation then null;end;
 if (select brand_name from public.settings where id=1)<>before_brand then raise exception 'Settings partially saved';end if;
 perform public.save_restaurant_settings(root,'Atomic brand','Tagline',0,0,false,false);
 if (select brand_name from public.settings where id=1)<>'Atomic brand' then raise exception 'Settings not saved';end if;
 url:='https://test.invalid/storage/v1/object/public/media/'||path;
 perform public.register_media_upload('media',path,url);
 insert into public.products(category_id,name,slug,price,is_available,image_url) select id,'GC Test',gen_random_uuid()::text,10000,false,url from public.categories limit 1 returning id into product;
 update tkm.media_uploads set updated_at=now()-interval '2 days' where bucket='media' and media_uploads.path=audit.path;
 candidate:=public.claim_unused_media();if candidate@>jsonb_build_array(jsonb_build_object('path',path)) then raise exception 'Referenced media collected';end if;
 update public.products set image_url=null where id=product;
 candidate:=public.claim_unused_media();if candidate@>jsonb_build_array(jsonb_build_object('path',path)) then raise exception 'Grace period ignored';end if;
 update tkm.media_uploads set updated_at=now()-interval '2 days' where bucket='media' and media_uploads.path=audit.path;
 candidate:=public.claim_unused_media();if not candidate@>jsonb_build_array(jsonb_build_object('path',path)) then raise exception 'Orphan not collected';end if;
 begin update public.products set image_url=url where id=product;raise exception 'Deleting media reattached';exception when check_violation then null;end;
 perform public.finish_media_cleanup('media',path);
 begin update public.products set image_url=url where id=product;raise exception 'Deleted media reattached';exception when check_violation then null;end;
 legacy_path:='products/'||gen_random_uuid()||'.webp';legacy_url:='https://legacy.invalid/storage/v1/object/public/media/'||legacy_path||'?v=1';
 insert into tkm.media_uploads(bucket,path,public_url) values('media',legacy_path,null);
 update public.products set image_url=legacy_url where id=product;
 update tkm.media_uploads set updated_at=now()-interval '2 days' where bucket='media' and media_uploads.path=legacy_path;
 candidate:=public.claim_unused_media();if candidate@>jsonb_build_array(jsonb_build_object('path',legacy_path)) then raise exception 'Referenced legacy media collected';end if;
 update public.products set image_url=null where id=product;
 update tkm.media_uploads set updated_at=now()-interval '2 days' where bucket='media' and media_uploads.path=legacy_path;
 candidate:=public.claim_unused_media();if not candidate@>jsonb_build_array(jsonb_build_object('path',legacy_path)) then raise exception 'Legacy orphan never collected';end if;
 perform public.finish_media_cleanup_batch('media',array[legacy_path]);
 begin update public.products set image_url=legacy_url where id=product;raise exception 'Legacy tombstone ignored';exception when check_violation then null;end;
 for f in select oid::regprocedure from pg_proc where proname in('begin_staff_edit','finish_staff_edit','archive_staff_account','save_restaurant_settings','claim_trusted_cashier_attempt','finish_trusted_cashier_login','register_media_upload','claim_unused_media','finish_media_cleanup','finish_media_cleanup_batch') loop
 if has_function_privilege('authenticated',f,'EXECUTE') or has_function_privilege('anon',f,'EXECUTE') then raise exception 'Public RPC grant %',f;end if;
 end loop;
end $$;
rollback;
